 #include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);

// Пины
const int startButton = 2;
const int resetButton = 3;
const int buzzerPin = 8;

// Переменные таймера
float time = 0.0;
bool running = false;

// millis() для таймера
unsigned long previousMillis = 0;
const long interval = 100; // обновление каждые 100 мс (1/10 сек)

// millis() для кнопок
unsigned long lastPressTime = 0;
const long debounceDelay = 200;

void setup() {
  lcd.init();
  lcd.backlight();

  pinMode(startButton, INPUT_PULLUP);
  pinMode(resetButton, INPUT_PULLUP);
  pinMode(buzzerPin, OUTPUT);
  noTone(buzzerPin);

  updateDisplay();
}

void loop() {
  //  Кнопка старт/стоп 
  if (digitalRead(startButton) == LOW) {
    if (millis() - lastPressTime > debounceDelay) {
      running = !running;
      lastPressTime = millis();
      if (running) {
        previousMillis = millis(); // сбрасываем таймер при запуске
      }
    }
  }

  //  Кнопка сброс 
  if (digitalRead(resetButton) == LOW) {
    if (millis() - lastPressTime > debounceDelay) {
      running = false;
      time = 0.0;
      lastPressTime = millis();
      noTone(buzzerPin);
      updateDisplay();
    }
  }

  //  Подсчёт времени 
  if (running) {
    unsigned long currentMillis = millis();
    if (currentMillis - previousMillis >= interval) {
      previousMillis = currentMillis;
      time += 0.1;
      updateDisplay();
    }
  }

  // Зуммер (если время кратно 10 секундам) 
  if (running && (int)(time * 10) % 100 == 0 && time > 0) {
    tone(buzzerPin, 1000, 100);
  }
}

void updateDisplay() {
  int minutes = (int)time / 60;
  int seconds = (int)time % 60;
  int tenths = (int)(time * 10) % 10;

  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("Stopwatch");
  lcd.setCursor(0, 1);

  if (minutes < 10) lcd.print("0");
  lcd.print(minutes);
  lcd.print(":");
  if (seconds < 10) lcd.print("0");
  lcd.print(seconds);
  lcd.print(":");
  lcd.print(tenths);
}

